import json,pathlib
p=pathlib.Path(__file__).resolve().parent
s=json.loads((p/'compact/summary.json').read_text())
lines=['','## 紧凑输入诊断（探索性，不是新测试集）','','在主基线后观察到Laya失败，额外将规则放到各题instructions，state只保留上下文与当前话语。所有三模型同样处理，每案例1次，共108请求。提示根据已知案例完善（含0.37米示例），因此结果只能解释提示敏感性，不能当作独立验证或替换主基线。未训练任何权重。','','| 模型 | 五字段全对 | route准确率 | P50/P95 ms | 0.8门控：正确执行/应执行 | 错发/发出 |','|---|---:|---:|---:|---:|---:|']
for m,v in s.items():
 g=v['gated'];lines.append(f'| {m} | {v["exact"]:.1%} | {v["fields"]["route"]:.1%} | {v["p50_ms"]:.0f}/{v["p95_ms"]:.0f} | {g["execution_recall"]:.1%} | {g["wrong_emitted"]}/{g["emitted"]} |')
lines+=['','## 本次建议','','1. 优先把pplx作为下一步Eidolon工具控制的云端基线：本次部署下比D3低延迟，主基线命令结果相同。不是模型在所有硬件/任务上的结论。','2. D3保持对照，未来有视觉输入再单独测。不能从本次文本测试推断视觉能力。','3. 通用Laya在两种输入格式下均不具备直接控制所需表现；此次没有测试家居r14或角色团权重，也不证明专门适配后的Laya不可用。','4. 自由数值和单位必须由独立解析器或结构化生成路径解决；复合任务转现有Agent规划执行。先补这两个环节，再决定是否训练。','5. 停止路径不应依赖公网推理的可用性和尾延迟，需要本地紧急停止入口及设备watchdog；语义层仍需区分否定与引用。','','补充观察：主基线三个模型在每例的三次重复中五字段选择均一致。D3/pplx的唯一route错误为C21：无活动任务时要求“小黄慢一点”，期望询问，两者选了拒绝；未造成错发。0.37米的漏执行是编译器槽位表达限制。零错发仅描述本小样本，不能估计线上风险。','']
with (p/'REPORT.md').open('a') as f:f.write('\n'.join(lines))
